// ---------------------------------------------------------------------------
// Python module
// ---------------------------------------------------------------------------

PYBIND11_MODULE(_C, m) {
  m.def("init", []() -> bool {
    return vkc_init() == 0;
  });
  m.def("is_available", []() -> bool {
    return vkc_is_available() == 1;
  });
  m.def("device_count", []() -> int64_t {
    return vkc_is_available() == 1 ? 1 : 0;
  });
  m.def("device_name", []() -> std::string {
    char buf[256];
    int n = vkc_device_name(buf, sizeof(buf));
    return n > 0 ? std::string(buf, n) : "N/A";
  });
  m.def("flush", []() -> int64_t {
    return vkc_flush() == 0 ? 1 : 0;
  });
  m.def("test_hello", []() -> int64_t {
    std::cout << "HELLO FROM C++!" << std::endl;
    return 42;
  });
  // --- Shader / dispatch API for the Inductor backend ---

  m.def("register_shader_handle", [](const std::string& op_name, int64_t handle) {
    g_shader_handles[op_name] = handle;
  });

  // Load SPIR-V bytecode, returns an opaque pipeline handle (int).
  m.def("load_shader", [](py::bytes spirv) -> int64_t {
    std::string data = spirv;
    void* handle = vkc_load_shader(
        reinterpret_cast<const uint8_t*>(data.data()), data.size());
    return reinterpret_cast<int64_t>(handle);
  });
  // Dispatch a compute shader over tensors.
  //   pipeline_handle: int64 from load_shader
  //   tensors: list of PrivateUse1 tensors (their data_ptrs are passed as buffers)
  //   group_count: (x, y, z) workgroup counts
  //   push_constants: bytes object for push constant data
  m.def("dispatch", [](
      int64_t pipeline_handle,
      std::vector<at::Tensor> tensors,
      std::tuple<uint32_t, uint32_t, uint32_t> group_count,
      py::bytes push_constants) -> bool {
    void* handle = reinterpret_cast<void*>(pipeline_handle);

    std::vector<const uint8_t*> ptrs;
    ptrs.reserve(tensors.size());
    for (auto& t : tensors) {
      ptrs.push_back(reinterpret_cast<const uint8_t*>(t.data_ptr()));
    }

    std::string pc_data = push_constants;
    auto [gx, gy, gz] = group_count;

    int32_t result = vkc_dispatch(
        handle,
        ptrs.data(),
        ptrs.size(),
        gx, gy, gz,
        reinterpret_cast<const uint8_t*>(pc_data.data()),
        pc_data.size());

    return result == 0;
  });
}
